head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > E > onmouseover]<br/>Textarea 컴포넌트 영역 내로 마우스 포인터가 들어 왔을 때 발생합니다.",
    "validation" : [
        "Textarea 컴포넌트 영역 내로 마우스 포인터가 들어왔을 때 onmouseover 이벤트가 발생합니다.",
        "이벤트 객체 e (MouseEvent) 가 핸들러에 전달됩니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cList = $c.gcm.createCList({});
    let eList = $c.gcm.createEList(["onmouseover"]);

    // target1 (textarea) 생성
    $c.gcm.createBasicTextArea(cList, eList);
}



// onmouseover 핸들러 - 발화 시점 확인용
scwin.target1_onmouseover = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmouseover 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
